//! Detection of the workspace layout (plain CMake project or colcon workspace).

use std::fs;
use std::path::{Path, PathBuf};

/// File generated by CMake in every build directory that has tests enabled.
const CTEST_FILE: &str = "CTestTestfile.cmake";

/// Kind of the opened workspace.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WorkspaceKind {
    /// A regular CMake project (source root or build directory).
    CMake,
    /// A ROS 2 colcon workspace (`build/<package>` per package).
    Colcon,
}

impl WorkspaceKind {
    pub fn label(self) -> &'static str {
        match self {
            WorkspaceKind::CMake => "CMake",
            WorkspaceKind::Colcon => "colcon",
        }
    }
}

/// A CMake build directory that ctest can be executed in.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Suite {
    /// Display name (package name for colcon, directory name for CMake).
    pub name: String,
    /// Directory containing `CTestTestfile.cmake`.
    pub build_dir: PathBuf,
}

/// The opened workspace.
#[derive(Debug, Clone)]
pub struct Workspace {
    pub root: PathBuf,
    pub kind: WorkspaceKind,
    pub suites: Vec<Suite>,
    /// Script sourced before running tests (colcon `install/setup.bash`).
    pub setup_script: Option<PathBuf>,
}

impl Workspace {
    /// Detects the workspace kind and its build directories under `root`.
    pub fn detect(root: &Path) -> Result<Workspace, String> {
        if !root.is_dir() {
            return Err(format!("{} is not a directory", root.display()));
        }

        if is_colcon_workspace(root) {
            let suites = suites_in(&root.join("build"));
            let setup = root.join("install").join("setup.bash");
            return Ok(Workspace {
                root: root.to_path_buf(),
                kind: WorkspaceKind::Colcon,
                suites,
                setup_script: setup.is_file().then_some(setup),
            });
        }

        let suites = if root.join(CTEST_FILE).is_file() {
            vec![Suite {
                name: dir_name(root),
                build_dir: root.to_path_buf(),
            }]
        } else {
            suites_in(root)
        };

        if suites.is_empty() {
            return Err(format!(
                "no {CTEST_FILE} found in {} or its sub directories; build the project with testing enabled first",
                root.display()
            ));
        }

        Ok(Workspace {
            root: root.to_path_buf(),
            kind: WorkspaceKind::CMake,
            suites,
            setup_script: None,
        })
    }
}

/// A colcon workspace has a `build` directory plus colcon generated markers.
fn is_colcon_workspace(root: &Path) -> bool {
    let build = root.join("build");
    let install = root.join("install");
    build.is_dir()
        && (build.join("COLCON_IGNORE").is_file()
            || install.join("COLCON_IGNORE").is_file()
            || install.join("setup.bash").is_file())
}

/// Returns the immediate sub directories of `dir` that contain a ctest file, sorted by name.
fn suites_in(dir: &Path) -> Vec<Suite> {
    let Ok(entries) = fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut suites: Vec<Suite> = entries
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.is_dir() && p.join(CTEST_FILE).is_file())
        .map(|p| Suite {
            name: dir_name(&p),
            build_dir: p,
        })
        .collect();
    suites.sort_by(|a, b| a.name.cmp(&b.name));
    suites
}

fn dir_name(path: &Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn touch(path: &Path) {
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, "").unwrap();
    }

    #[test]
    fn detects_cmake_build_directory_itself() {
        let tmp = tempfile::tempdir().unwrap();
        touch(&tmp.path().join(CTEST_FILE));

        let ws = Workspace::detect(tmp.path()).unwrap();
        assert_eq!(ws.kind, WorkspaceKind::CMake);
        assert_eq!(ws.suites.len(), 1);
        assert_eq!(ws.suites[0].build_dir, tmp.path());
    }

    #[test]
    fn detects_cmake_source_root_with_build_dirs() {
        let tmp = tempfile::tempdir().unwrap();
        touch(&tmp.path().join("CMakeLists.txt"));
        touch(&tmp.path().join("build-release").join(CTEST_FILE));
        touch(&tmp.path().join("build").join(CTEST_FILE));
        fs::create_dir_all(tmp.path().join("src")).unwrap();

        let ws = Workspace::detect(tmp.path()).unwrap();
        assert_eq!(ws.kind, WorkspaceKind::CMake);
        let names: Vec<_> = ws.suites.iter().map(|s| s.name.as_str()).collect();
        assert_eq!(names, ["build", "build-release"]);
        assert!(ws.setup_script.is_none());
    }

    #[test]
    fn detects_colcon_workspace() {
        let tmp = tempfile::tempdir().unwrap();
        touch(&tmp.path().join("build").join("COLCON_IGNORE"));
        touch(&tmp.path().join("build").join("pkg_b").join(CTEST_FILE));
        touch(&tmp.path().join("build").join("pkg_a").join(CTEST_FILE));
        fs::create_dir_all(tmp.path().join("build").join("py_pkg")).unwrap();
        touch(&tmp.path().join("install").join("setup.bash"));

        let ws = Workspace::detect(tmp.path()).unwrap();
        assert_eq!(ws.kind, WorkspaceKind::Colcon);
        let names: Vec<_> = ws.suites.iter().map(|s| s.name.as_str()).collect();
        assert_eq!(names, ["pkg_a", "pkg_b"]);
        assert_eq!(
            ws.setup_script.as_deref(),
            Some(tmp.path().join("install").join("setup.bash").as_path())
        );
    }

    #[test]
    fn errors_when_nothing_found() {
        let tmp = tempfile::tempdir().unwrap();
        assert!(Workspace::detect(tmp.path()).is_err());
        assert!(Workspace::detect(&tmp.path().join("missing")).is_err());
    }
}
